import{_ as t,P as n,d as i,e as o,y as r,q as s}from"./chunks/framework.D7CAgLCq.js";const g=JSON.parse('{"title":"Receiving a message is not yet effective feedback","description":"Trace what returns, where it arrives, and what it changes afterward.","frontmatter":{"title":"Receiving a message is not yet effective feedback","description":"Trace what returns, where it arrives, and what it changes afterward."},"headers":[],"relativePath":"en/concepts/feedback.md","filePath":"en/concepts/feedback.md"}'),c={name:"en/concepts/feedback.md"};function h(d,e,l,p,f,m){const a=n("FeedbackExplorer");return i(),o("div",null,[e[0]||(e[0]=r('<h1 id="receiving-a-message-is-not-yet-effective-feedback" tabindex="-1">Receiving a message is not yet effective feedback <a class="header-anchor" href="#receiving-a-message-is-not-yet-effective-feedback" aria-label="Permalink to &quot;Receiving a message is not yet effective feedback&quot;">​</a></h1><p>A receipt shows that a signal arrived. Under the book’s definition in §3.3, <strong>effective feedback requires a return channel to make a detectable difference to a later state, transition probability, timing, or constraint</strong>, relative to no return or a blocked return.</p><h2 id="follow-the-change" tabindex="-1">Follow the change <a class="header-anchor" href="#follow-the-change" aria-label="Permalink to &quot;Follow the change&quot;">​</a></h2><p>The book’s hypothetical complaint example separates receipt, a changed case-status item, and actual execution. An office can record an appeal without changing the service decision. It can then change the decision in its database without implementing the remedy. Each record has a real, narrower meaning; none should silently stand for the whole process.</p><p>Track the prior state or output, the return channel, the receiving position, and the subsequent item that is changed. To attribute the difference to feedback, inspect the comparison and competing explanations. A change after a complaint is not automatically a change caused by that complaint.</p><p>“Effective” describes an effect here, not praise. A delayed or misleading signal may change behavior and make the outcome worse. A fixed controller can produce feedback without learning new parameters or storing a lasting memory. Stability, improvement, learning, and authorization require additional arguments.</p><h2 id="a-documented-example" tabindex="-1">A documented example <a class="header-anchor" href="#a-documented-example" aria-label="Permalink to &quot;A documented example&quot;">​</a></h2><p>The EPA Inspector General’s 2018 Flint report records 87 resident complaints received by Region 5 between May 2014 and January 2016; 30 mentioned lead. The office sent form letters, while 11 complaints had no documented response. Complaint volume was not used as an indicator of a water-system problem. These findings locate specific failures; they do not prove that every complaint had no effect of any kind. See <a href="./../cases/flint-water-feedback.html">the Flint case</a>, with report pages and later follow-up.</p><p>The <a href="./../cases/toyota-andon.html">Toyota Andon case</a> offers a different source type: a company’s published description of how notification connects to response and resumption of work. It illustrates a specified process, without proving universal implementation or an independent quality effect.</p><h2 id="try-the-distinction" tabindex="-1">Try the distinction <a class="header-anchor" href="#try-the-distinction" aria-label="Permalink to &quot;Try the distinction&quot;">​</a></h2><p>Suppose a report causes an inspection to happen earlier, but the hazard remains. If the timing effect is supported, effective feedback can exist. Whether the response protected residents is a separate outcome. Conversely, an automatic “received” message alone does not establish a change in the service or risk assessment that matters to the inquiry.</p><p>Read <a href="/xi-kari-skill/handbook/en/theory/part-03.html#section-3-3">§3.3</a>, <a href="/xi-kari-skill/handbook/en/theory/part-06.html#section-6-4">§6.4</a>, and <a href="./history.html">feedback-mediated learning</a>. The hypothetical complaint is a conceptual illustration, not an empirical study.</p><h2 id="explore-the-teaching-model" tabindex="-1">Explore the teaching model <a class="header-anchor" href="#explore-the-teaching-model" aria-label="Permalink to &quot;Explore the teaching model&quot;">​</a></h2>',13)),s(a)])}const b=t(c,[["render",h]]);export{g as __pageData,b as default};
